// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        SelfDestructing helper = new SelfDestructing();
        vm.deal(address(helper), amount);
        uint256 before = address(c).balance;
        c.forward(address(helper), "");
        assertTrue(address(c).balance == before + amount);
    }
}

contract SelfDestructing {
    fallback() external payable {
        selfdestruct(payable(msg.sender));
    }
}
